import functools
def repeat(n):
    def deco(f):
        @functools.wraps(f)
        def w(*a,**k):
            return [f(*a,**k) for _ in range(n)]
        return w
    return deco
@repeat(3)
def hi(name): 'greet'; return f'hi {name}'
print(hi('a'), hi.__name__)
